def stable_group_pairs(pairs):
    groups = []
    seen = []
    for key, value in pairs:
        if key in seen:
            idx = seen.index(key)
            groups[idx].append(value)
        else:
            seen.append(key)
            groups.append([value])
    return [[k, v] for k, v in zip(seen, groups)]
